load("/sfz/nosql-02-payments.js")

// one payment, with room for its refunds inside it
db.payments.updateOne({ _id: "pay-81002" }, { $set: { refundedMinor: 0, refunds: [] } })

// a refund is ONE update: MongoDB checks the filter and applies it to one document atomically
const refund = (id, amount) => db.payments.updateOne(
  { _id: "pay-81002", status: "SETTLED", $expr: { $lte: [{ $add: ["$refundedMinor", amount] }, "$amountMinor"] } },
  { $push: { refunds: { refundId: id, amountMinor: amount, at: new Date() } }, $inc: { refundedMinor: amount } })
refund("ref-1", 6000).modifiedCount
refund("ref-2", 6000).modifiedCount
db.payments.findOne({ _id: "pay-81002" }, { amountMinor: 1, refundedMinor: 1, "refunds.refundId": 1 })

// the types BSON stored for the amounts, counted
db.payments.aggregate([{ $group: { _id: { $type: "$amountMinor" }, n: { $sum: 1 } } }]).toArray()

// an old import job once stored an amount as text
db.payments.insertOne({ _id: "pay-79999", accountId: "A-1001", merchantId: "M-0042", status: "SETTLED", amountMinor: "42.50", currency: "EUR", createdAt: new Date("2026-11-06T12:00:00Z") })

// the rule from now on: whole-number amounts of at least 1, one of three statuses, a real date
const rule = { $jsonSchema: { bsonType: "object", required: ["accountId", "merchantId", "status", "amountMinor", "createdAt"],
  properties: { status: { enum: ["AUTHORIZED", "SETTLED", "FAILED"] },
                amountMinor: { bsonType: ["int", "long"], minimum: 1 },
                createdAt: { bsonType: "date" } } } }
db.runCommand({ collMod: "payments", validator: rule, validationLevel: "strict" }).ok

// strict checks every new write...
db.payments.insertOne({ _id: "pay-90001", accountId: "A-1001", merchantId: "M-0042", status: "PENDING", amountMinor: 4250, createdAt: new Date() })

// ...but not the documents already there. constraint (new in 9.0) checks those too
db.runCommand({ collMod: "payments", prepareConstraintValidationLevel: true }).ok
db.runCommand({ collMod: "payments", validationLevel: "constraint", validationAction: "error" })
db.payments.updateOne({ _id: "pay-79999" }, { $set: { amountMinor: 4250 } }).modifiedCount
db.runCommand({ collMod: "payments", validationLevel: "constraint", validationAction: "error" }).ok

// M-0042's day, by status: WHERE, then GROUP BY, then ORDER BY
const daily = [
  { $match: { merchantId: "M-0042", createdAt: { $gte: ISODate("2026-11-07T00:00:00Z"), $lt: ISODate("2026-11-08T00:00:00Z") } } },
  { $group: { _id: "$status", payments: { $sum: 1 }, amountMinor: { $sum: "$amountMinor" }, largest: { $max: "$amountMinor" } } },
  { $sort: { _id: 1 } }
]
db.payments.aggregate(daily)

// what did it read? the first stage hands the $match to the query planner
const c = db.payments.explain("executionStats").aggregate(daily).stages[0].$cursor
const chain = (s) => s ? [s.stage, ...chain(s.inputStage)] : []
({ plan: chain(c.queryPlanner.winningPlan.queryPlan).join(" > "), keysExamined: c.executionStats.totalKeysExamined, docsExamined: c.executionStats.totalDocsExamined })

