code.src:
-- one payment per row, refunds inside the document
CREATE TEMP TABLE payment_doc (id text PRIMARY KEY, doc jsonb NOT NULL);
INSERT INTO payment_doc VALUES
  ('pay-81002', '{"status": "SETTLED", "amountMinor": 6837, "refundedMinor": 0, "refunds": []}');

-- the guarded refund: checked and applied to one row in one statement
PREPARE refund(text, bigint) AS
UPDATE payment_doc
   SET doc = jsonb_set(
               jsonb_set(doc, '{refundedMinor}', to_jsonb((doc->>'refundedMinor')::bigint + $2)),
               '{refunds}', doc->'refunds' || jsonb_build_object('refundId', $1, 'amountMinor', $2))
 WHERE id = 'pay-81002'
   AND doc->>'status' = 'SETTLED'
   AND (doc->>'refundedMinor')::bigint + $2 <= (doc->>'amountMinor')::bigint;
EXECUTE refund('ref-1', 6000);
EXECUTE refund('ref-2', 6000);
SELECT doc->'refundedMinor' AS refunded, jsonb_array_length(doc->'refunds') AS refunds FROM payment_doc;

-- an old import left a text amount behind
INSERT INTO payment_doc VALUES ('pay-79999', '{"status": "SETTLED", "amountMinor": "42.50", "refundedMinor": 0, "refunds": []}');

-- schema-on-write for the parts you name: every row, like MongoDB 9.0's constraint level
ALTER TABLE payment_doc ADD CONSTRAINT amount_is_number CHECK (jsonb_typeof(doc->'amountMinor') = 'number');
-- new writes only, like strict
ALTER TABLE payment_doc ADD CONSTRAINT amount_is_number CHECK (jsonb_typeof(doc->'amountMinor') = 'number') NOT VALID;
INSERT INTO payment_doc VALUES ('pay-90001', '{"status": "SETTLED", "amountMinor": "99.00", "refundedMinor": 0, "refunds": []}');
-- fix the old row, then check every row
UPDATE payment_doc SET doc = jsonb_set(doc, '{amountMinor}', '4250') WHERE id = 'pay-79999';
ALTER TABLE payment_doc VALIDATE CONSTRAINT amount_is_number;

